INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6988286, 1055289, 6804, '<td valign="top">This is a remarkable picture!  I am very biased of the 4 corners area.  A photographers playground, for sure.  Im happy to see youve kept all the mid-tones intact and made the effort to shoot during the ideal time of the day. .  ..   ..   ..   The border is dreadful!  It is overwhelming the image.   I see youve selected a color from the photo, but it isnt at all a complimentary color to the work.  It is a distraction.   <br/>All-in-all, high marks from me.  Good luck in the challenge!</td>', 'This is a remarkable picture!  I am very biased of the 4 corners area.  A photographers playground, for sure.  Im happy to see youve kept all the mid-tones intact and made the effort to shoot during the ideal time of the day. .  ..   ..   ..   The border is dreadful!  It is overwhelming the image.   I see youve selected a color from the photo, but it isnt at all a complimentary color to the work.  It is a distraction.   All-in-all, high marks from me.  Good luck in the challenge!', '2013-03-01 00:47:01.000000', NULL, 1),
(6988300, 1055553, 152252, '<td valign="top">I remember her from one of the challenges. Still captures my attention. Definitely looks beautiful in B&amp;W!</td>', 'I remember her from one of the challenges. Still captures my attention. Definitely looks beautiful in B&W!', '2013-03-01 00:54:02.000000', NULL, 1),
(6988306, 1055771, 152252, '<td valign="top">Beautiful vibrant colors and a lovely, interesting individual. Amazing portrait!</td>', 'Beautiful vibrant colors and a lovely, interesting individual. Amazing portrait!', '2013-03-01 00:56:45.000000', NULL, 1),
(6988308, 1055768, 6804, '<td valign="top">This is such a beautiful image!  Very well done!  The processing is exceptional!<br/>I am so disappointed that she is looking at her phone!<br/>She should be thinking or sipping her drink or. Anything but looking at her phone.  <br/>Still high marks from me.</td>', 'This is such a beautiful image!  Very well done!  The processing is exceptional!I am so disappointed that she is looking at her phone!She should be thinking or sipping her drink or. Anything but looking at her phone.  Still high marks from me.', '2013-03-01 00:57:00.000000', NULL, 1),
(6988314, 1055647, 152252, '<td valign="top">This just blew my mind away. Great dramatic effect!</td>', 'This just blew my mind away. Great dramatic effect!', '2013-03-01 00:58:20.000000', NULL, 1),
(6988319, 1055214, 152252, '<td valign="top">They look so lovely close together. I love their colors against the green grass. The tree definitely adds to the whole composition.</td>', 'They look so lovely close together. I love their colors against the green grass. The tree definitely adds to the whole composition.', '2013-03-01 01:00:07.000000', NULL, 1),
(6988324, 1054771, 152252, '<td valign="top">I like that you cut it that way yet still have the person''s reflection. Looks very mysterious and makes me wonder about the subject''s life. Love it in B&amp;W</td>', 'I like that you cut it that way yet still have the person''s reflection. Looks very mysterious and makes me wonder about the subject''s life. Love it in B&W', '2013-03-01 01:04:05.000000', NULL, 1),
(6988327, 1055637, 113411, '<td valign="top">fabulous !!!</td>', 'fabulous !!!', '2013-03-01 01:04:34.000000', NULL, 1),
(6988331, 1055198, 6804, '<td valign="top">-  That''s it?  That''s your title???  :-)  I love it!<br/>I''m not sure what I''m looking at.. so, as good art performs... i see the things that relate to me...   It looks like a golf club thrown into the water out of frustration. ...   or maybe a fallen branch on a quiet morning, drifting away to the sunny side of the island.  Its very simple... which makes it hard to hang on a wall.  But the depth that it pulls from this viewer put''s the score well above the average shot in this contest.  High marks from me.   Good luck in the challenge.</td>', '-  That''s it?  That''s your title???  :-)  I love it!I''m not sure what I''m looking at.. so, as good art performs... i see the things that relate to me...   It looks like a golf club thrown into the water out of frustration. ...   or maybe a fallen branch on a quiet morning, drifting away to the sunny side of the island.  Its very simple... which makes it hard to hang on a wall.  But the depth that it pulls from this viewer put''s the score well above the average shot in this contest.  High marks from me.   Good luck in the challenge.', '2013-03-01 01:05:48.000000', NULL, 1),
(6988333, 1055433, 152252, '<td valign="top">Reminds me of Jagar. Very well done! Great subject, textures and B&amp;W</td>', 'Reminds me of Jagar. Very well done! Great subject, textures and B&W', '2013-03-01 01:07:30.000000', NULL, 1),
(6988335, 1054453, 152252, '<td valign="top">Amazing tones, subject and place. &lt;3</td>', 'Amazing tones, subject and place. <3', '2013-03-01 01:08:31.000000', NULL, 1),
(6988339, 1055934, 152252, '<td valign="top">Beautiful macro, excellent colors!</td>', 'Beautiful macro, excellent colors!', '2013-03-01 01:10:18.000000', NULL, 1),
(6988340, 1055667, 6804, '<td valign="top">A flying wilder beast!  Who''d a thunk it?   This is indeed art at it''s finest!   The image makes me laugh!   it''s a fantastic shot!  I hope it does well in the challenge, but..... You know these voters are all so misguided.</td>', 'A flying wilder beast!  Who''d a thunk it?   This is indeed art at it''s finest!   The image makes me laugh!   it''s a fantastic shot!  I hope it does well in the challenge, but..... You know these voters are all so misguided.', '2013-03-01 01:11:02.000000', NULL, 1),
(6988342, 1055732, 152252, '<td valign="top">Great capture! Love the symmetry of the real scene and the reflections</td>', 'Great capture! Love the symmetry of the real scene and the reflections', '2013-03-01 01:12:08.000000', NULL, 1),
(6988345, 1055723, 152252, '<td valign="top">It tells the story well. I love the processing/tones</td>', 'It tells the story well. I love the processing/tones', '2013-03-01 01:14:28.000000', NULL, 1),
(6988354, 1056029, 152252, '<td valign="top">Very well executed! Love the processing. Blue eyes look great with the red hat.</td>', 'Very well executed! Love the processing. Blue eyes look great with the red hat.', '2013-03-01 01:21:50.000000', NULL, 1),
(6988375, 1055214, 117534, '<td valign="top">Wow very painterly and beautiful!!</td>', 'Wow very painterly and beautiful!!', '2013-03-01 01:34:52.000000', NULL, 1),
