(6989097, 1055530, 10785, '<td valign="top">This is my choice for the blue! The light and shadow, the color, the perspective, the foreground and background elements all work to create a magical scene of a lost world tucked away!!</td>', 'This is my choice for the blue! The light and shadow, the color, the perspective, the foreground and background elements all work to create a magical scene of a lost world tucked away!!', '2013-03-01 20:42:57.000000', NULL, 1),
(6989102, 1055828, 136989, '<td valign="top">I like everything except the pole in the middle and its reflection. It''s distracting from the calm of the water and the interest in the reeds.  Of course wading out to move it would likely be cold and scare the birds.  Great depth and feel.</td>', 'I like everything except the pole in the middle and its reflection. It''s distracting from the calm of the water and the interest in the reeds.  Of course wading out to move it would likely be cold and scare the birds.  Great depth and feel.', '2013-03-01 20:59:43.000000', NULL, 1),
(6989104, 1055009, 136989, '<td valign="top">Love it!!  Great comp and balance of dark and light.  So much detail in air and on the water.  Your fisherman is framed quite nicely and ripples too.  :)</td>', 'Love it!!  Great comp and balance of dark and light.  So much detail in air and on the water.  Your fisherman is framed quite nicely and ripples too.  :)', '2013-03-01 21:07:28.000000', NULL, 1),
