INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6989109, 1055933, 136989, '<td valign="top">Gorgeous sky!  Sunsets are just great aren''t they?  I like how the white of the cottage pops against the background.</td>', 'Gorgeous sky!  Sunsets are just great aren''t they?  I like how the white of the cottage pops against the background.', '2013-03-01 21:14:40.000000', NULL, 1),
(6989111, 1055241, 136989, '<td valign="top">The starbursts here really take the photo from ordinary into art.  It adds that dramatic flare the brings the blues and greens to life among the shadows. Very nice.</td>', 'The starbursts here really take the photo from ordinary into art.  It adds that dramatic flare the brings the blues and greens to life among the shadows. Very nice.', '2013-03-01 21:16:17.000000', NULL, 1),
(6989113, 1056000, 136989, '<td valign="top">This shot takes ordinary to extraordinary. So simple yet so much going on.  Great dof.  The colors and lighting are wonderful.  The vines seem to be reaching for the sun.</td>', 'This shot takes ordinary to extraordinary. So simple yet so much going on.  Great dof.  The colors and lighting are wonderful.  The vines seem to be reaching for the sun.', '2013-03-01 21:17:48.000000', NULL, 1),
(6989115, 1054984, 136989, '<td valign="top">Very dramatic.  Nice balance of light and dark.  The bottom right on the water may be a little washed out but it does help lead the eye to the stones so it does work.</td>', 'Very dramatic.  Nice balance of light and dark.  The bottom right on the water may be a little washed out but it does help lead the eye to the stones so it does work.', '2013-03-01 21:19:22.000000', NULL, 1),
(6989117, 1055530, 136989, '<td valign="top">I love the color here and so much to catch the eye.  I could see this as an illustration in a fairy tale.  The curious hero/heroine sneaks into the garden and views the cottage door from afar...</td>', 'I love the color here and so much to catch the eye.  I could see this as an illustration in a fairy tale.  The curious hero/heroine sneaks into the garden and views the cottage door from afar...', '2013-03-01 21:20:53.000000', NULL, 1),
