(6993488, 1055668, 108580, '<td valign="top">I recognise that chair from a previous <strike>life</strike> challenge :P<br/>Lens baby or Vaseline. They both look the same to me! What is intriguing is that the end result is deemed art. To me it''s a style/technique that is "arty" in it''s own right/ Pretty much a fleeting dream deja vu.</td>', 'I recognise that chair from a previous life challenge :PLens baby or Vaseline. They both look the same to me! What is intriguing is that the end result is deemed art. To me it''s a style/technique that is "arty" in it''s own right/ Pretty much a fleeting dream deja vu.', '2013-03-07 01:15:31.000000', NULL, 1),
(6993489, 1055794, 123833, '<td valign="top">Cutout?</td>', 'Cutout?', '2013-03-07 01:15:33.000000', NULL, 1),
(6993491, 1054453, 123833, '<td valign="top">This feels surreal. Great image</td>', 'This feels surreal. Great image', '2013-03-07 01:16:15.000000', NULL, 1),
(6993502, 1055224, 108580, '<td valign="top">Arty for sure. Good zoom technique.</td>', 'Arty for sure. Good zoom technique.', '2013-03-07 01:32:25.000000', NULL, 1),
(6993504, 1055723, 108580, '<td valign="top">Naturally they were hanging and are now inverted, a good technique to keep them looking like they are floating yet punctured. Artistic surely. I like the tones. Reminds me of a plugin preset :)</td>', 'Naturally they were hanging and are now inverted, a good technique to keep them looking like they are floating yet punctured. Artistic surely. I like the tones. Reminds me of a plugin preset :)', '2013-03-07 01:33:45.000000', NULL, 1),
(6993509, 1055521, 108580, '<td valign="top">Printable. Great subject and Composition.</td>', 'Printable. Great subject and Composition.', '2013-03-07 01:38:10.000000', NULL, 1),
(6993512, 1055266, 97225, '<td valign="top">Beautiful! Top shot!</td>', 'Beautiful! Top shot!', '2013-03-07 01:40:28.000000', NULL, 1),
(6993513, 1055508, 108580, '<td valign="top">A Chameleon in a building! Nice tie in to the poster. Good PP.</td>', 'A Chameleon in a building! Nice tie in to the poster. Good PP.', '2013-03-07 01:41:02.000000', NULL, 1),
(6993516, 1054595, 108580, '<td valign="top">Has the feeling of a Sanatorium. The overlay or opaqueness is painterly, soft, and is counter to the pain the subject appears to be in. One of the more artistic entries so far.</td>', 'Has the feeling of a Sanatorium. The overlay or opaqueness is painterly, soft, and is counter to the pain the subject appears to be in. One of the more artistic entries so far.', '2013-03-07 01:46:57.000000', NULL, 1),
(6993519, 1055667, 108580, '<td valign="top">A tried and tested style to portray wildlife and one I still find quite appealing despite a massive resurgence online of it. I''d prefer more work in the white areas to remove some blemishes.</td>', 'A tried and tested style to portray wildlife and one I still find quite appealing despite a massive resurgence online of it. I''d prefer more work in the white areas to remove some blemishes.', '2013-03-07 01:52:09.000000', NULL, 1),
