INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6993587, 1054695, 86218, '<td valign="top">Beautiful. Image with soul</td>', 'Beautiful. Image with soul', '2013-03-07 07:14:56.000000', NULL, 1),
(6993592, 1055053, 108580, '<td valign="top">It certainly fades over time but it is never completely gone...</td>', 'It certainly fades over time but it is never completely gone...', '2013-03-07 07:35:57.000000', NULL, 1),
(6993603, 1055553, 135629, '<td valign="top">This was my top pick, great lighting, great tones, a beautiful photo.</td>', 'This was my top pick, great lighting, great tones, a beautiful photo.', '2013-03-07 08:29:13.000000', NULL, 1),
(6993604, 1055985, 135629, '<td valign="top">Super interesting photo, in my top 2 for this challenge. Very far and above the architectural shots that have become so common. Awesome lighting and colors!</td>', 'Super interesting photo, in my top 2 for this challenge. Very far and above the architectural shots that have become so common. Awesome lighting and colors!', '2013-03-07 08:30:40.000000', NULL, 1),
(6993606, 1054432, 135629, '<td valign="top">Great shot, one of my top picks. How many takes did this require?</td>', 'Great shot, one of my top picks. How many takes did this require?', '2013-03-07 08:31:25.000000', NULL, 1),
(6993625, 1055433, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>B&amp;W tones are fabulous! The man standing there looks to be waiting for more ''guests'' to arrive. With only 4 pigeons ''at the table'' there is room for more to join in on the feast:-) It makes me wonder where is he keeping the food for the birds - mayhap in his pant pocket? Nice capture of a slice of life.</td>', 'Voted earlier coming back to comment. B&W tones are fabulous! The man standing there looks to be waiting for more ''guests'' to arrive. With only 4 pigeons ''at the table'' there is room for more to join in on the feast:-) It makes me wonder where is he keeping the food for the birds - mayhap in his pant pocket? Nice capture of a slice of life.', '2013-03-07 09:17:06.000000', NULL, 1),
(6993630, 1055241, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Love the angle of composition, color and clarity of this shot. The bench promises to give the audience a front row seat for maximum ''illumination''. I wonder how many ''epihanies'' or breakthroughs there have been from just on that bench sitting, relaxing and calmly thinking upon the problem or question...<br/>I do have two critiques/observations. The detail is tack sharp but the slight blur to the grass in the lower right quadrant looks rather odd in my eyes. Second, I think if the picture was a little darker (not too dark) it would further strengthen the symbology of seeking illumination and further boast the ambience.</td>', 'Voted earlier coming back to comment. Love the angle of composition, color and clarity of this shot. The bench promises to give the audience a front row seat for maximum ''illumination''. I wonder how many ''epihanies'' or breakthroughs there have been from just on that bench sitting, relaxing and calmly thinking upon the problem or question...I do have two critiques/observations. The detail is tack sharp but the slight blur to the grass in the lower right quadrant looks rather odd in my eyes. Second, I think if the picture was a little darker (not too dark) it would further strengthen the symbology of seeking illumination and further boast the ambience.', '2013-03-07 09:26:19.000000', NULL, 1),
(6993631, 1056028, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>This is such a lovely nature shot! I love the old style camera is included in the composition for it adds an additional subject of interest (especially to us photographers:-) ) The thing that I feel spoils the beauty of the shot and composition is the processing. The colors are way too bold that they become garrish to look at. The greens, yellows, and reds are oversaturated in color. To a lesser extent the level of detail could also be toned down just a little because it too suffers a tad of being too oversharp.</td>', 'Voted earlier coming back to comment. This is such a lovely nature shot! I love the old style camera is included in the composition for it adds an additional subject of interest (especially to us photographers:-) ) The thing that I feel spoils the beauty of the shot and composition is the processing. The colors are way too bold that they become garrish to look at. The greens, yellows, and reds are oversaturated in color. To a lesser extent the level of detail could also be toned down just a little because it too suffers a tad of being too oversharp.', '2013-03-07 09:30:54.000000', NULL, 1),
(6993632, 1055289, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Absolutely love the light that plays on the desert illuminating those lone mountain outcroppings and the plains below. Great colors that show off the beauty of this place in the hush of the early morning hours.</td>', 'Voted earlier coming back to comment. Absolutely love the light that plays on the desert illuminating those lone mountain outcroppings and the plains below. Great colors that show off the beauty of this place in the hush of the early morning hours.', '2013-03-07 09:34:59.000000', NULL, 1),
(6993639, 1054536, 109387, '<td valign="top">Just a simple, yet effective moment in time - one of my favorites :)</td>', 'Just a simple, yet effective moment in time - one of my favorites :)', '2013-03-07 09:49:06.000000', NULL, 1),
(6993641, 1055680, 109387, '<td valign="top">Someone could not consider this one as ''art'' but I do - wonderful :)</td>', 'Someone could not consider this one as ''art'' but I do - wonderful :)', '2013-03-07 09:50:31.000000', NULL, 1),
