(6993669, 1055616, 109227, '<td valign="top">I like this whimsical image very much.  Nice find. (bumping up)</td>', 'I like this whimsical image very much.  Nice find. (bumping up)', '2013-03-07 10:44:45.000000', NULL, 1),
(6993670, 1055909, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>There is a bit of nostalgia, the beauty of the everyday, and a story being played out here. The lighting and mood of the composition makes me think that this is a recalled memory. The event has long since past but the observance/watching of it lingers long in the memory. Perhaps it is a fond memory of a beloved pet playing with her favorite toy or perhaps it is a fond memory of how Lulu reacted/welcomed a ''new comer'' to her personal window to the world.</td>', 'Voted earlier coming back to comment. There is a bit of nostalgia, the beauty of the everyday, and a story being played out here. The lighting and mood of the composition makes me think that this is a recalled memory. The event has long since past but the observance/watching of it lingers long in the memory. Perhaps it is a fond memory of a beloved pet playing with her favorite toy or perhaps it is a fond memory of how Lulu reacted/welcomed a ''new comer'' to her personal window to the world.', '2013-03-07 10:45:18.000000', NULL, 1),
(6993671, 1055433, 109227, '<td valign="top">I think I have seen these bw tones before and they are still magnificent.  Great simplistic image.</td>', 'I think I have seen these bw tones before and they are still magnificent.  Great simplistic image.', '2013-03-07 10:45:58.000000', NULL, 1),
(6993672, 1055466, 109227, '<td valign="top">Beautiful high key image.</td>', 'Beautiful high key image.', '2013-03-07 10:46:17.000000', NULL, 1),
(6993673, 1055767, 109227, '<td valign="top">Sad but wonderful imagery.  Would like to know if there is a story behind it.</td>', 'Sad but wonderful imagery.  Would like to know if there is a story behind it.', '2013-03-07 10:47:14.000000', NULL, 1),
(6993674, 1056000, 109227, '<td valign="top">I really like these kind of images, simple, natural and wistful.</td>', 'I really like these kind of images, simple, natural and wistful.', '2013-03-07 10:47:42.000000', NULL, 1),
(6993675, 1055549, 109227, '<td valign="top">Great human and animal moment; detail is outstanding.</td>', 'Great human and animal moment; detail is outstanding.', '2013-03-07 10:48:03.000000', NULL, 1),
