INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6995073, 1055530, 158576, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by pixelpig:</b></div><hr/><i> I like the color, but I''m not able to make any logical sense of the tree branch that disappears under the doors (windows), comes up on the other side, &amp; goes toward the sky. The light has no logic to it either, for me. I hope you will put in some notes to help me understand. </i></td></tr></table> <br/> <br/>There is no tree branch that disappears under the doors. I think you''re mistaking a crack in the wood floor for a tree branch. I''m not sure what you mean the light having "no logic to it". This was shot in morning light, the sun was coming from the photos upper right and was filtered by trees and the remains of other parts of the building.</td>', 'Originally posted by pixelpig: I like the color, but I''m not able to make any logical sense of the tree branch that disappears under the doors (windows), comes up on the other side, & goes toward the sky. The light has no logic to it either, for me. I hope you will put in some notes to help me understand.   There is no tree branch that disappears under the doors. I think you''re mistaking a crack in the wood floor for a tree branch. I''m not sure what you mean the light having "no logic to it". This was shot in morning light, the sun was coming from the photos upper right and was filtered by trees and the remains of other parts of the building.', '2013-03-08 06:18:01.000000', NULL, 0),
(6995078, 1054948, 68769, '<td valign="top">My eyes go back and forth between the woman, and the background both holding my interest. Art indeed..</td>', 'My eyes go back and forth between the woman, and the background both holding my interest. Art indeed..', '2013-03-08 06:36:22.000000', NULL, 0),
