(6995141, 1055092, 19825, '<td valign="top">A beautifully composed shot enhanced by processing. A beauty. You have such an excellent eye for dark dreamy images, and you have done well carving out a unique niche in the top tier of the challenges often heavy with glossy, staged shot. Congratulations on finishing in the top 10 three years running. Art judged by the masses seems so fickle to me -- consistent high finishes is quite an accomplishment.</td>', 'A beautifully composed shot enhanced by processing. A beauty. You have such an excellent eye for dark dreamy images, and you have done well carving out a unique niche in the top tier of the challenges often heavy with glossy, staged shot. Congratulations on finishing in the top 10 three years running. Art judged by the masses seems so fickle to me -- consistent high finishes is quite an accomplishment.', '2013-03-08 08:50:55.000000', NULL, 0),
(6995148, 1054478, 61961, '<td valign="top">Two first places on the same day?  That must be rare!  Congratulations.  Lovely photo, too!</td>', 'Two first places on the same day?  That must be rare!  Congratulations.  Lovely photo, too!', '2013-03-08 08:59:11.000000', NULL, 0),
(6995153, 1055401, 61961, '<td valign="top">Perfect moment, the square crop highlights the symmetry, and you ignored (!) the rule of thirds with your horizon line, which gives the whole photo a contemporary feel.  An engaging mix of candid and created.  This photo really draws me in.</td>', 'Perfect moment, the square crop highlights the symmetry, and you ignored (!) the rule of thirds with your horizon line, which gives the whole photo a contemporary feel.  An engaging mix of candid and created.  This photo really draws me in.', '2013-03-08 09:03:46.000000', NULL, 0),
